// Contract between the Video Studio app (../../../studio) and the videos it builds.
// Every studio project lives in src/studio/<projectId>/ and its index.tsx exports
// COMPOSITIONS. registry.tsx (generated by the studio server) registers them all.
import React from 'react';

export type StudioComp = {
  id: string; // must be unique, letters/numbers/hyphens only
  component: React.FC<any>;
  durationInFrames: number;
  fps: number;
  width: number;
  height: number;
  defaultProps?: Record<string, unknown>;
};
